#pragma once
#include <cstdint>

namespace omni {

namespace blobkey {

namespace c_core {
/**
 * Value for C interfaces to handle Key types
 */
constexpr int KEY_SIZE = 32;

/**
 * Value to represent size of arrays to hold printable Key strings
 */

/**
 * Represents various types of status of client operations from the client
 */
typedef enum blobhash_status {
  /**
   * Everything was okay
   */
  blobhash_status_success,
  /**
   * Size hint given was too small (in practice, this means it was 0)
   */
  blobhash_status_size_underflow,
  /**
   * Size hint given was too large to be represented.
   */
  blobhash_status_size_overflow,
  /**
   * Integrity check failed
   */
  blobhash_status_integ_fail,
  /**
   * Size hint in BlobHash smaller than given blob in check
   */
  blobhash_status_blobsizehint_mismatch,
  /**
   * Conversion from raw bytes failed to produce a valid key
   */
  blobhash_status_invalid_key,
} blobhash_status;

/**
 * Represents various types of status of client operations from the client
 */
typedef enum blobkey_status {
  /**
   * Everything was okay
   */
  blobkey_status_success,
  /**
   * String passed for hex conversion wasn't actually a hexstring, or the right length
   */
  blobkey_status_invalid_hex,
  /**
   * Conversion from raw bytes failed to produce a valid key
   */
  blobkey_status_invalid_key,
  /**
   * Blobsize given cannot be represented
   */
  blobkey_status_blobsizehint_overflow,
  /**
   * Blobsize given cannot be represented
   */
  blobkey_status_blobsizehint_underflow,
  /**
   * Catch-all error
   */
  blobkey_status_unknown_error,
} blobkey_status;

/**
 * Represents various types of status of client operations from the client
 */
typedef enum keyhash_status {
  /**
   * Everything was okay
   */
  keyhash_status_success,
  /**
   * Key given was too small (in practice, this means it was 0)
   */
  keyhash_status_key_size_underflow,
  /**
   * Size hint given was too smal (in practice, this means it was 0)
   */
  keyhash_status_blob_size_underflow,
  /**
   * Size hint given was too large to be represented.
   */
  keyhash_status_blob_size_overflow,
} keyhash_status;

/**
 * represents different available namespaces
 */
enum blobkey_enum {
  /**
   * See blobhash::BlobHash; this hashes a blob's contents. Size hint is for blob.
   */
  blobkey_namespace_blob_hash = 1,
  /**
   * See keyhash::KeyHash; this hashes a key to a new key, (but the size hint is for the blob).
   */
  blobkey_namespace_key_hash = 2,
};
typedef uint8_t blobkey_namespace;

/**
 * Opaquified Key
 */
struct alignas(8) blobkey {
  /**
   * `Anonmyous` payload
   */
  uint8_t _f[KEY_SIZE];
};

typedef blobkey blobhash;
/**
 * Namespace-dictated content
 */
struct blobkey_payload {
  /**
   * `anonymous` data
   */
  uint8_t _data[28];
};
} // namespace c_core
} // namespace blobkey
} // namespace omni
